<?php require __DIR__.'/../includes/core.php';require_login(['admin']);$sessions=all('SELECT * FROM academic_sessions ORDER BY id DESC');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if($_POST['action']==='session'){sql('INSERT INTO academic_sessions(name) VALUES (?)',[trim($_POST['name'])]);}elseif($_POST['action']==='cycle'){sql('INSERT INTO evaluation_cycles(session_id,term,starts_at,ends_at,is_open) VALUES (?,?,?,?,1)',[(int)$_POST['session_id'],trim($_POST['term']),$_POST['starts_at']?:null,$_POST['ends_at']?:null]);}elseif($_POST['action']==='toggle'){sql('UPDATE evaluation_cycles SET is_open=1-is_open WHERE id=?',[(int)$_POST['id']]);}audit('cycle_configuration');flash('Saved.');go('admin/cycles.php');}$cycles=all('SELECT c.*,s.name session_name FROM evaluation_cycles c JOIN academic_sessions s ON s.id=c.session_id ORDER BY c.id DESC');ob_start();?><div class="card"><h2>Add academic session</h2><form method="post"><?=token()?><input type="hidden" name="action" value="session"><input name="name" placeholder="2027/2028" required><p><button>Add session</button></p></form></div><div class="card"><h2>Create evaluation cycle</h2><form method="post"><?=token()?><input type="hidden" name="action" value="cycle"><div class="formgrid"><div><label>Session</label><select name="session_id"><?php foreach($sessions as $s)echo '<option value="'.$s['id'].'">'.h($s['name']).'</option>';?></select></div><div><label>Term</label><select name="term"><option>First Term</option><option>Second Term</option><option>Third Term</option></select></div><div><label>Opens</label><input type="date" name="starts_at"></div><div><label>Closes</label><input type="date" name="ends_at"></div></div><p><button>Create cycle</button></p></form></div><div class="card"><h2>Evaluation cycles</h2><div class="tablewrap"><table><tr><th>Session</th><th>Term</th><th>Dates</th><th>Status</th><th>Action</th></tr><?php foreach($cycles as $c){echo '<tr><td>'.h($c['session_name']).'</td><td>'.h($c['term']).'</td><td>'.h($c['starts_at']).' — '.h($c['ends_at']).'</td><td>'.($c['is_open']?'Open':'Closed').'</td><td><form method="post">'.token().'<input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="'.$c['id'].'"><button>Toggle</button></form></td></tr>';}?></table></div></div><?php layout('Academic sessions & evaluation cycles',ob_get_clean());